  bool Descendant(string id,string ancestor){for(int i=0;i<128&&id!=null;i++){var p=Project.parts.Find(x=>x.id==id);id=p?.parent;if(id==ancestor)return true;}return false;}
  void AddAction(string type){var p=Project.parts.Find(x=>x.id==Selected);var a=new RobotAction{name=type=="move"?p.name+" hareketi":type=="emit"?"Atış / bırakma":"Intake çalıştır",partId=Selected,type=type,key=type=="emit"?"Space":"KeyR",button="",from=p.Copy(),to=p.Copy()};if(Project.season=="2026"){a.piece="fuel";if(type=="emit")a.consume=true;if(type=="capture")a.captureEfficiency=.7;}if(type=="capture"){a.spawn=p.id=="chassis"?new[]{Project.drive.dimensions[0]*.5,0,.02}:new[]{0.0,0,0};a.captureSize=p.id=="chassis"?new[]{.25,Project.drive.dimensions[1],.25}:(double[])p.size.Clone();a.key="KeyI";a.button="leftBumper";}if(type=="emit")a.spawn=DefaultMuzzle(Selected);Project.actions.Add(a);SelectRobotAction(a);}
